// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _run(address sender, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint256 prev;
        try c.balances(sender) returns (uint256 __r) { prev = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        assertTrue(c.balances(sender) - prev <= amount);
    }

    function testFuzz_run(address sender, uint256 amount) public {
        _run(sender, amount);
    }

    receive() external payable {}
}
